<script>
(function(){
"use strict";
const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s));
const NS="http://www.w3.org/2000/svg";
function el(tag,attrs,txt){const e=document.createElementNS(NS,tag);for(const k in attrs)e.setAttribute(k,attrs[k]);if(txt!=null)e.textContent=txt;return e;}
function cv(n){return getComputedStyle(document.body).getPropertyValue(n).trim();}
function clr(id){$("#"+id).innerHTML="";}

/* ============ 主题 / 进度 / 目录 ============ */
$("#tbtn").onclick=()=>{
  const cur=document.documentElement.getAttribute("data-theme");
  document.documentElement.setAttribute("data-theme",cur==="dark"?"light":"dark");
  draw1();draw3();draw7();
};
const secs=$$("main section"), links=$$("#toc a:not(.sub)");
function onScroll(){
  const h=document.documentElement;
  $("#prog").style.width=(h.scrollTop/(h.scrollHeight-h.clientHeight)*100)+"%";
  let cur=secs[0].id;
  for(const s of secs){ if(s.getBoundingClientRect().top<=120) cur=s.id; }
  links.forEach(a=>a.classList.toggle("on",a.getAttribute("href")==="#"+cur));
}
document.addEventListener("scroll",onScroll,{passive:true}); onScroll();

/* ============ 工具 ============ */
function fmtDown(min){
  if(min<1) return (min*60).toFixed(1)+" 秒";
  if(min<60) return min.toFixed(1)+" 分钟";
  if(min<1440) return (min/60).toFixed(1)+" 小时";
  if(min<43200) return (min/1440).toFixed(1)+" 天";
  return (min/43200).toFixed(1)+" 个月";
}
function fmtAvail(a){
  const p=a*100;
  if(p>99.999) return p.toFixed(6)+"%";
  if(p>99.99) return p.toFixed(5)+"%";
  if(p>99.9) return p.toFixed(4)+"%";
  if(p>99) return p.toFixed(3)+"%";
  return p.toFixed(2)+"%";
}
function comb(n,k){let r=1;for(let i=0;i<k;i++)r=r*(n-i)/(i+1);return r;}

/* ============ 实验 1 · 可用性计算器 ============ */
const AV=[0.9,0.99,0.995,0.999,0.9995,0.9999,0.99999];
const YEARMIN=365.25*24*60;
function draw1(){
  const p=AV[+$("#r1a").value], N=+$("#r1n").value;
  $("#l1a").textContent=fmtAvail(p); $("#l1n").textContent=N;
  const ser=Math.pow(p,N), par=1-Math.pow(1-p,N);
  const k=Math.floor(N/2)+1; let q=0;
  for(let i=k;i<=N;i++) q+=comb(N,i)*Math.pow(p,i)*Math.pow(1-p,N-i);
  q=Math.min(1,Math.max(0,q));
  const set=(idv,idu,a)=>{$("#"+idv).textContent=fmtAvail(a);$("#"+idu).textContent="年停机 "+fmtDown((1-a)*YEARMIN);};
  set("v1s","u1s",ser); set("v1p","u1p",par); set("v1q","u1q",q);
  $("#v1t").textContent=k+" / "+N;

  const svg=$("#sv1"); svg.innerHTML="";
  const W=640,PADL=86,PADR=26,TOP=16,BH=26,GAP=22;
  const LO=-1.1, HI=5.75;                       // log10(分钟)
  const x=v=>{const L=Math.log10(Math.max(v,Math.pow(10,LO)));
    return PADL+(Math.min(Math.max(L,LO),HI)-LO)/(HI-LO)*(W-PADL-PADR);};
  const ticks=[[1,"1分"],[60,"1时"],[1440,"1天"],[10080,"1周"],[43200,"1月"],[525960,"1年"]];
  const baseY=TOP+3*(BH+GAP)-GAP+10;
  ticks.forEach(t=>{
    svg.appendChild(el("line",{x1:x(t[0]),y1:TOP-6,x2:x(t[0]),y2:baseY,stroke:cv("--grid"),"stroke-width":1}));
    svg.appendChild(el("text",{x:x(t[0]),y:baseY+15,fill:cv("--ink-3"),"font-size":10,"text-anchor":"middle","font-family":cv("--sans")},t[1]));
  });
  svg.appendChild(el("text",{x:W-PADR,y:baseY+31,fill:cv("--ink-3"),"font-size":10,"text-anchor":"end","font-family":cv("--sans")},"年停机时间（对数刻度）"));
  const rows=[["串联",ser,cv("--s2")],["并联",par,cv("--s1")],["多数派",q,cv("--s3")]];
  rows.forEach((r,i)=>{
    const y=TOP+i*(BH+GAP), dm=Math.max((1-r[1])*YEARMIN,0.02), w=Math.max(x(dm)-PADL,3);
    svg.appendChild(el("text",{x:PADL-12,y:y+BH/2+4,fill:cv("--ink-2"),"font-size":12,"text-anchor":"end","font-family":cv("--sans")},r[0]));
    svg.appendChild(el("rect",{x:PADL,y:y,width:w,height:BH,rx:4,fill:r[2]}));
    svg.appendChild(el("rect",{x:PADL,y:y,width:Math.min(w,4),height:BH,fill:r[2]}));
    const lx=PADL+w+8;
    svg.appendChild(el("text",{x:Math.min(lx,W-6),y:y+BH/2+4,fill:cv("--ink"),"font-size":11.5,
      "text-anchor":lx>W-100?"end":"start","font-family":cv("--sans")},fmtDown((1-r[1])*YEARMIN)+" · "+fmtAvail(r[1])));
  });
}
$("#r1a").oninput=draw1; $("#r1n").oninput=draw1; draw1();

/* ============ 实验 2 · 不可靠网络沙盒 ============ */
const CX=92, SX=548, MY=112;
const S2={pk:[],biz:new Map(),next:1,total:0,ok:0,fail:0,exec:0,pulse:0,pulseC:0};
function log2(msg,color){
  const box=$("#lg2"); if(box.children.length===1&&box.children[0].classList.contains("tsp"))box.innerHTML="";
  const d=document.createElement("div");
  d.innerHTML='<span class="tsp">'+String(box.children.length+1).padStart(3,"0")+'</span>  '+
    (color?'<span style="color:'+color+'">'+msg+'</span>':msg);
  box.appendChild(d); box.scrollTop=box.scrollHeight;
  while(box.children.length>300) box.removeChild(box.firstChild);
}
const p2=()=>({loss:+$("#r2d").value/100,lat:+$("#r2l").value,jit:+$("#r2j").value,to:+$("#r2t").value,retry:$("#c2r").checked});
function lat2(){const c=p2();return Math.max(40,c.lat+(Math.random()*2-1)*c.jit);}
function attempt(b){
  const c=p2(), now=performance.now();
  b.att++; b.deadline=now+c.to;
  const lost=Math.random()<c.loss;
  S2.pk.push({dir:1,t0:now,dur:lat2(),lost:lost,lossAt:0.25+Math.random()*0.5,biz:b.id,att:b.att});
  log2("→ 请求 #"+b.id+" 第"+b.att+"次发出"+(c.retry?"":"（不重试模式）"));
}
function newBiz(){
  const b={id:S2.next++,att:0,done:false,deadline:0}; S2.biz.set(b.id,b); S2.total++; attempt(b); upd2();
}
function upd2(){
  $("#v2c").textContent=S2.total; $("#v2ok").textContent=S2.ok;
  $("#v2f").textContent=S2.fail; $("#v2s").textContent=S2.exec;
  const g=S2.exec-S2.ok;
  const e=$("#v2gap"); e.textContent=(g>0?"+":"")+g;
  e.style.color=g===0?cv("--ink"):(g>0?cv("--crit"):cv("--serious"));
}
function frame2(){
  const now=performance.now(), c=p2(), svg=$("#sv2");
  for(let i=S2.pk.length-1;i>=0;i--){
    const p=S2.pk[i], pr=(now-p.t0)/p.dur;
    if(p.lost&&pr>=p.lossAt){S2.pk.splice(i,1);log2("✗ "+(p.dir===1?"请求":"响应")+"包 #"+p.biz+" 在网络中丢失",cv("--serious"));continue;}
    if(pr>=1){
      S2.pk.splice(i,1);
      if(p.dir===1){
        S2.exec++; S2.pulse=now; S2.pulseC=cv("--warn");
        log2("⚙ 服务器执行 #"+p.biz+"（第"+p.att+"次到达）· 累计执行 "+S2.exec+" 次",cv("--warn"));
